          longDescription:'English 10 is a second-year high-school English Language Arts course aligned to the Common Core State Standards for Grades 9–10. Unit 1, Rhetoric and Argument, teaches the rhetorical situation (SOAPSTone), the appeals of ethos, pathos, logos and kairos, rhetorical devices, and how to evaluate claims, evidence and fallacies (RI.9-10.6, RI.9-10.8), using public-domain speeches such as Lincoln’s Gettysburg Address. It then applies these tools to Shakespeare’s The Tragedy of Julius Caesar, comparing the funeral speeches of Brutus and Antony, and ends with a full argument essay (W.9-10.1). Later units cover world literature, the novel, poetry, research writing and drama. Every lesson builds listening, speaking, reading and writing, with worked examples, leveled practice, a workshop, a quiz, an assignment with a four-level rubric, and a review.',
